COMMENT ON COLUMN bza_attachment.scan_status IS 'PENDING/CLEAN/INFECTED/FAILED/QUARANTINED';
COMMENT ON COLUMN bza_attachment.data_classification IS 'PUBLIC/INTERNAL/CONFIDENTIAL/RESTRICTED';
COMMENT ON COLUMN bza_attachment.retention_until IS '보존 만료시각';
COMMENT ON COLUMN bza_attachment.quarantine_yn IS '격리 여부';
COMMENT ON COLUMN bza_attachment.use_yn IS '사용 여부';
COMMENT ON COLUMN bza_attachment.created_by IS '등록자';
COMMENT ON COLUMN bza_attachment.created_at IS '등록일시';
COMMENT ON COLUMN bza_attachment.updated_by IS '수정자';
COMMENT ON COLUMN bza_attachment.updated_at IS '수정일시';
